{
  "settings": [
    {
      "evidence": "| `FORMAT` | Specifies the copy function to use. The default is selected from the file extension (e.g., `.parquet` results in a Parquet file being written/read). If the file extension is unknown `CSV` is selected. Vanilla DuckDB provides `CSV`, `PARQUET` and `JSON` but additional copy functions can be added by [`extensions`]({% link docs/current/extensions/overview.md %}). | `VARCHAR` | `auto` |",
      "input_type": "DOUBLE",
      "name": "FORMAT",
      "scope": "GLOBAL"
    },
    {
      "evidence": "| `USE_TMP_FILE` | Whether or not to write to a temporary file first if the original file exists (`target.csv.tmp`). This prevents overwriting an existing file with a broken file in case the writing is cancelled. | `BOOL` | `auto` |",
      "input_type": "BOOLEAN",
      "name": "USE_TMP_FILE",
      "scope": "GLOBAL"
    },
    {
      "evidence": "| `OVERWRITE_OR_IGNORE` | Whether or not to allow overwriting files if they already exist. Only has an effect when used with options that write multiple files, such as `PARTITION_BY`, `PER_THREAD_OUTPUT` or `FILE_SIZE_BYTES`. | `BOOL` | `false` |",
      "input_type": "BOOLEAN",
      "name": "OVERWRITE_OR_IGNORE",
      "scope": "GLOBAL"
    },
    {
      "evidence": "| `OVERWRITE` | When `true`, all existing files inside targeted directories will be removed (not supported on remote filesystems). Only has an effect when used with options that write multiple files, such as `PARTITION_BY`, `PER_THREAD_OUTPUT` or `FILE_SIZE_BYTES`. | `BOOL` | `false` |",
      "input_type": "BOOLEAN",
      "name": "OVERWRITE",
      "scope": "GLOBAL"
    },
    {
      "evidence": "| `APPEND` | When `true`, in the event a filename pattern is generated that already exists, the path will be regenerated to ensure no existing files are overwritten. Only has an effect when used with options that write multiple files, such as `PARTITION_BY`, `PER_THREAD_OUTPUT` or `FILE_SIZE_BYTES`. | `BOOL` | `false` |",
      "input_type": "BOOLEAN",
      "name": "APPEND",
      "scope": "GLOBAL"
    },
    {
      "evidence": "| `FILENAME_PATTERN` | Set a pattern to use for the filename, can optionally contain `{uuid}` / `{uuidv4}` or `{uuidv7}` to be filled in with a generated [UUID]({% link docs/current/sql/data_types/numeric.md %}#universally-unique-identifiers-uuids) (v4 or v7, respectively), and `{i}`, which is replaced by an incrementing index. Only has an effect when used with options that write multiple files, such as `PARTITION_BY`, `PER_THREAD_OUTPUT` or `FILE_SIZE_BYTES`. | `VARCHAR` | `auto` |",
      "input_type": "VARCHAR",
      "name": "FILENAME_PATTERN",
      "scope": "GLOBAL"
    },
    {
      "evidence": "| `FILE_EXTENSION` | Set the file extension that should be assigned to the generated file(s). | `VARCHAR` | `auto` |",
      "input_type": "VARCHAR",
      "name": "FILE_EXTENSION",
      "scope": "GLOBAL"
    },
    {
      "evidence": "| `PER_THREAD_OUTPUT` | When `true`, the `COPY` command generates one file per thread, rather than one file in total. This allows for faster parallel writing. | `BOOL` | `false` |",
      "input_type": "BOOLEAN",
      "name": "PER_THREAD_OUTPUT",
      "scope": "GLOBAL"
    },
    {
      "evidence": "| `FILE_SIZE_BYTES` | If this parameter is set, the `COPY` process creates a directory which will contain the exported files. If a file exceeds the set limit (specified as bytes such as `1000` or in human-readable format such as `1k`), the process creates a new file in the directory. This parameter works in combination with `PER_THREAD_OUTPUT`. Note that the size is used as an approximation, and files can be occasionally slightly over the limit. | `VARCHAR` or `BIGINT` | (empty) |",
      "input_type": "VARCHAR",
      "name": "FILE_SIZE_BYTES",
      "scope": "GLOBAL"
    },
    {
      "evidence": "| `PARTITION_BY` | The columns to partition by using a Hive partitioning scheme, see the [partitioned writes section]({% link docs/current/data/partitioning/partitioned_writes.md %}). | `VARCHAR[]` | (empty) |",
      "input_type": "VARCHAR[]",
      "name": "PARTITION_BY",
      "scope": "GLOBAL"
    },
    {
      "evidence": "| `PRESERVE_ORDER` | Whether or not to [preserve order]({% link docs/current/sql/dialect/order_preservation.md %}) during the copy operation. Defaults to the value of the `preserve_insertion_order` [configuration option]({% link docs/current/configuration/overview.md %}). | `BOOL`| (*) |",
      "input_type": "BOOLEAN",
      "name": "PRESERVE_ORDER",
      "scope": "GLOBAL"
    },
    {
      "evidence": "| `RETURN_FILES` | Whether or not to include the created filepath(s) (as a `files VARCHAR[]` column) in the query result. | `BOOL` | `false` |",
      "input_type": "BOOLEAN",
      "name": "RETURN_FILES",
      "scope": "GLOBAL"
    },
    {
      "evidence": "| `RETURN_STATS` | Whether or not to return the files and their column statistics that were written as part of the `COPY` statement. | `BOOL`| `false` |",
      "input_type": "BOOLEAN",
      "name": "RETURN_STATS",
      "scope": "GLOBAL"
    },
    {
      "evidence": "| `WRITE_PARTITION_COLUMNS` | Whether or not to write partition columns into files. Only has an effect when used with `PARTITION_BY`. | `BOOL` | `false` |",
      "input_type": "BOOLEAN",
      "name": "WRITE_PARTITION_COLUMNS",
      "scope": "GLOBAL"
    }
  ]
}
